function legend(){const m=metric();if(m==='c58'||m==='c21'){$('lg').innerHTML=`<span><i class="sw" style="background:#7a1f12"></i>21 個里：下水道圖還是舊圖</span><span><i class="sw" style="background:${m==='c58'?'#b5452c':'#efc0ae'}"></i>58 個里的其餘 37 個</span><span><i class="sw" style="background:#ece8e1"></i>其他里</span><span>${ICN.nm}夜市（黑點，市場處名單）</span><span>${ICN.gb}垃圾車停靠點（綠點；橘點是選定的半小時有車到）</span><span>${ICN.mh}人孔（拉近才出現；實心是實測，空心圈是舊圖轉繪）</span><span>餐飲多 = 餐飲密度前三分之一；停靠點少 = 每千人停靠點後三分之一或 0；舊圖 = 人孔原圖轉繪比例前三分之一</span>`;return}if(m==='inv'){$('lg').innerHTML=Object.entries(INVN).reverse().map(([k,v])=>`<span><i class="sw" style="background:${INVC[k]}"></i>${v}</span>`).join('')+'<span>食源高 = OSM 餐飲密度前三分之一；未實測高 = 人孔原圖轉繪比例前三分之一（反映資料品質）；清運少 = 每千人停靠點最少的三分之一或 0（只算家戶收運）</span>';return}if(m==='spray'){$('lg').innerHTML=Object.entries(SPRAYN).map(([k,v])=>`<span><i class="sw" style="background:${SPRAYC[k]}"></i>${v}</span>`).join('')+'<span>（每組預估 38 組次，單價 3,350 到 3,800 元；合約設計按區平均，實際投放量沒公開）</span>';return}
 const[lo,hi]=RANGE[m];const c=fillOf({[m]:hi,spray:0}),c0=fillOf({[m]:lo,spray:0});$('lg').innerHTML=`<span><i class="sw" style="background:${c0}"></i>${LAB[m][0]}</span><span><i class="sw" style="background:${c}"></i>${LAB[m][1]}</span>`+(m==='dRat10k'||m==='rat10k'?'<span>通報是志工行為，不是老鼠</span>':'')}
function tip(p){return `<div class="ltip"><b>${p.dist} ${p.li}</b><br>餐飲 ${p.eat}（每平方公里 ${p.eatKm2}）、超商 ${p.conv}、市場 ${p.mkt}<br>人孔 ${p.mh}（每平方公里 ${p.mhKm2}，原圖轉繪 ${Math.round(p.mhUnsurv*100)}%）<br>清潔箱 ${p.bins}${PUB?'':'<br>見鼠通報 '+p.rat+'（5 月 '+p.ratMay+'、之後 '+p.ratAfter+'）'}</div>`}
function mini(arr,cls){const mx=Math.max(1,...arr);return `<div class="mini ${cls||''}">${arr.map(v=>`<i style="height:${Math.max(1,Math.round(v/mx*44))}px" title="${v}"></i>`).join('')}</div>`}
function showInfo(p){const d=DIST[p.dist]||{};const rows=[['人口 / 面積',`${p.pop.toLocaleString()} / ${p.area} 平方公里`],['餐飲（OpenStreetMap）',`${p.eat}（每平方公里 ${p.eatKm2}、每萬人 ${p.eat10k}）`],['超商 / 市場',`${p.conv} / ${p.mkt}`],['雨水下水道人孔',`${p.mh}（每平方公里 ${p.mhKm2}）`],['人孔原圖轉繪（未實測）',`${Math.round(p.mhUnsurv*100)}%`],['行人專用清潔箱點位',p.bins],['病媒噴藥契約區組（109 年）',SPRAYN[p.spray]||'—'],['垃圾車停靠點 / 車次（家戶收運）',`${p.stops} / ${p.trips}（每千人 ${p.stops1k}；${p.first||'—'} 到 ${p.last||'—'}）`],['主張',p.c21?'21 個里之一：垃圾清運的優先區域，下水道需要定期清理並恢復紀錄':(p.c58?'58 個里之一：垃圾清運的優先區域':'不在 58 個里裡')],[`${p.dist}隊側溝清疏 2026 年 1 到 8 月`,`${p.ditchM.toLocaleString()} 公尺`],[`${p.dist}稅籍餐飲 / 見鼠通報`,`${(d.food||0).toLocaleString()} 家 / ${d.rat?d.rat.reduce((a,b)=>a+b,0):0} 筆（每萬人 ${d.rat10k||0}）`]];
 if(!PUB)rows.push(['本里見鼠通報（內部）',`${p.rat}（5 月 ${p.ratMay}、之後 ${p.ratAfter}；每萬人 ${p.rat10k}）`]);
 $('info').innerHTML=`<b class="t">${p.dist} ${p.li}</b><table>${rows.map(r=>`<tr><td>${r[0]}</td><td style="text-align:right">${r[1]}</td></tr>`).join('')}</table><div class="k">${p.dist}的見鼠通報月序（5 到 10 月）</div>${mini(d.rat||[])}<div class="k">${(d.months||[]).map(m=>m.slice(5)).join('　')}</div>`}
function styleLi(f){const p=f.properties;const m=metric();const cl=(m==='c58'||m==='c21');const em=cl&&p.c21,fr=!cl&&p.c58;return {color:sel===p.id?'#1f4e79':(em||fr?'#3d0f08':'#fff'),weight:sel===p.id?3:(em?1.6:(fr?1.4:0.7)),fillColor:fillOf(p),fillOpacity:(map.getZoom()>=15?(cl?(p.c58?0.35:0.15):0.3):(cl?(p.c58?0.88:0.5):0.72))}}
function refresh(){legend();if(liLayer)liLayer.setStyle(styleLi)}
function overlay(key,make,minZoom){const cb=$(key);const on=()=>{const want=cb.checked&&(!minZoom||map.getZoom()>=minZoom);if(want){if(!ov[key])ov[key]=make();if(!map.hasLayer(ov[key]))ov[key].addTo(map)}else if(ov[key]&&map.hasLayer(ov[key]))map.removeLayer(ov[key])};cb.addEventListener('change',on);if(minZoom)map.on('zoomend',on);on()}
liLayer=L.geoJSON(LI,{style:styleLi,onEachFeature:(f,l)=>{l.bindTooltip(()=>tip(f.properties),{sticky:true});l.on('click',()=>{sel=f.properties.id;liLayer.setStyle(styleLi);showInfo(f.properties)})}}).addTo(map);
refresh();
{const b=L.latLngBounds([]);LI.features.forEach(f=>{if(f.properties.c58)f.geometry.coordinates.forEach(r=>r.forEach(q=>b.extend([q[1],q[0]])))});if(b.isValid())map.fitBounds(b,{padding:[18,18]})}
const NM=[[121.51528, 25.05581, "寧夏夜市", "left", 0, 0], [121.51106, 25.06578, "延三夜市", "left", 0, 0], [121.51598, 25.07181, "大龍夜市", "right", 0, 0], [121.57508, 25.05067, "饒河街夜市", "right", 0, 0], [121.49839, 25.03831, "華西街夜市", "right", 1, 0], [121.49758, 25.03653, "梧州街夜市", "bottom", 1, 0], [121.49761, 25.037, "廣州街夜市", "left", 1, 0], [121.50069, 25.04042, "西昌街夜市", "right", 1, 0], [121.50592, 25.02947, "南機場夜市", "right", 0, 0], [121.53512, 25.01324, "公館夜市", "right", 0, 0], [121.52433, 25.06444, "雙城街夜市", "right", 0, 1], [121.54222, 25.04936, "遼寧街夜市", "right", 0, 0], [121.55525, 25.03006, "臨江街夜市", "right", 0, 0], [121.54175, 24.99083, "景美夜市", "right", 0, 0], [121.52419, 25.08808, "士林夜市", "right", 0, 0]];let nmL=null;
function nmMk(lon,lat,html,dir,r){const m=L.circleMarker([lat,lon],{radius:r,color:'#fff',weight:1.5,fillColor:'#1c1c1c',fillOpacity:1});const off=dir==='left'?[-r-2,0]:(dir==='bottom'?[0,r+2]:[r+2,0]);m.bindTooltip(html,{permanent:true,direction:dir,offset:off,className:'nmk'});return m}
function nmOn(){if(nmL){map.removeLayer(nmL);nmL=null}if(!$('ov_nm').checked)return;const z=map.getZoom(),g=L.layerGroup();NM.forEach(a=>{if(a[4]&&z<15)return;g.addLayer(nmMk(a[0],a[1],a[2],a[3],5))});if(z<15){const c=NM.filter(a=>a[4]),nm=c.map(a=>a[2].replace('夜市',''));g.addLayer(nmMk(c.reduce((s,a)=>s+a[0],0)/c.length,c.reduce((s,a)=>s+a[1],0)/c.length,nm.slice(0,2).join('・')+'<br>'+nm.slice(2).join('・')+'夜市','left',6))}nmL=g.addTo(map)}
$('ov_nm').addEventListener('change',nmOn);map.on('zoomend',nmOn);nmOn();
const GB58=PTS.gb.filter(a=>a[6]);let gb58L=null;const hm=s=>s.slice(0,2)+':'+s.slice(2);const hh=t=>String(Math.floor(t)).padStart(2,'0')+':'+(t%1?'30':'00');
const gbIn=(a,t)=>{const h=parseInt(a[2].slice(0,2))+parseInt(a[2].slice(2))/60;return h>=t&&h<t+0.5};
function gb58On(){if(gb58L){map.removeLayer(gb58L);gb58L=null}const t=+$('gbT').value;$('gbTl').textContent=hh(t)+' 到 '+hh(t+0.5);
 $('gbTn').textContent=`這半小時全市有 ${PTS.gb.filter(a=>gbIn(a,t)).length} 個停靠點有車到，58 個里裡有 ${GB58.filter(a=>gbIn(a,t)).length} 個（橘點）。`;
 if(!$('ov_gb58').checked)return;const g=L.layerGroup();GB58.forEach(a=>{const on=gbIn(a,t);g.addLayer(L.circleMarker([a[1],a[0]],{radius:on?6:4,color:'#fff',weight:1,fillColor:on?'#e67e22':'#1e8449',fillOpacity:on?1:0.8}).bindPopup(`<b>垃圾車</b> ${hm(a[2])} 到、${hm(a[3])} 走<br>路線 ${a[4]}、車次 ${a[5]}<br>${a[7]||''}`))});gb58L=g.addTo(map)}
$('gbT').addEventListener('input',gb58On);$('ov_gb58').addEventListener('change',gb58On);gb58On();
overlay('ov_mh',()=>L.layerGroup(PTS.mh.map(a=>L.circleMarker([a[1],a[0]],a[2]?{radius:3.5,color:'#fff',weight:0.8,fillColor:'#1f4e79',fillOpacity:0.9}:{radius:3.5,color:'#1f4e79',weight:1.8,fillColor:'#fff',fillOpacity:1}).bindTooltip(`人孔（${a[2]?'實測':'原圖轉繪，未實測'}）${a[3]||''}`))),14);
map.on('zoomend',()=>{if(liLayer)liLayer.setStyle(styleLi)});

overlay('ov_eat',()=>L.layerGroup(PTS.eat.map(a=>L.circleMarker([a[1],a[0]],{radius:2.5,color:'#8b2e1f',weight:0.5,fillColor:'#c0392b',fillOpacity:0.7}).bindTooltip(`${a[2]} ${a[3]||''}`))),15);
overlay('ov_conv',()=>L.layerGroup(PTS.conv.map(a=>L.circleMarker([a[1],a[0]],{radius:3,color:'#1f4e79',weight:0.5,fillColor:'#2874a6',fillOpacity:0.8}).bindTooltip(`${a[2]} ${a[3]||''}`))),14);
overlay('ov_mkt',()=>L.layerGroup([...PTS.pub.map(a=>L.circleMarker([a[1],a[0]],{radius:6,color:'#fff',weight:1,fillColor:'#b7791f',fillOpacity:1}).bindTooltip(`公有零售市場 ${a[2]}<br>${a[3]||''}`+(PUB||a.length<5?'':`<br>300 公尺內見鼠通報 ${a[4]}（內部）`))),...PTS.mkt.map(a=>L.circleMarker([a[1],a[0]],{radius:4,color:'#b7791f',weight:1,fillColor:'#fff',fillOpacity:1}).bindTooltip(`${a[2]} ${a[3]||''}`))]));
overlay('ov_gb',()=>L.layerGroup(PTS.gb.map(a=>L.circleMarker([a[1],a[0]],{radius:3,color:'#fff',weight:0.5,fillColor:'#1e8449',fillOpacity:0.85}).bindTooltip(`垃圾車 ${a[2].slice(0,2)}:${a[2].slice(2)} 到 ${a[3].slice(0,2)}:${a[3].slice(2)}　${a[4]} ${a[5]}`))),14);
document.querySelectorAll('.btns button').forEach(b=>b.addEventListener('click',()=>{CUR=b.dataset.m;document.querySelectorAll('.btns button').forEach(x=>x.classList.toggle('on',x===b));refresh()}));
